\begin{aligned}
Pr(\mathbf{x}|\phi) &= \int Pr(\mathbf{x}, \mathbf{z}|\phi) d\mathbf{z} \\
&= \int Pr(\mathbf{x}|\mathbf{z}, \phi) \cdot Pr(\mathbf{z}) d\mathbf{z} \\
&= \int \operatorname{Norm}_{\mathbf{x}}\left[\mathbf{f}[\mathbf{z}, \phi], \sigma^2 \mathbf{I}\right] \cdot \operatorname{Norm}_{\mathbf{z}}[0, \mathbf{I}] \, d\mathbf{z}.
\end{aligned}

